package com.campusbite.requests;
import org.springframework.web.server.ResponseStatusException;
import com.campusbite.orders.*;import com.campusbite.users.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/cooking-requests")
public class CookingRequestController {
 private final CookingRequestRepository repo;private final OrderRepository orders;private final UserRepository users;
 public CookingRequestController(CookingRequestRepository r,OrderRepository o,UserRepository u){repo=r;orders=o;users=u;}
 @PostMapping @PreAuthorize("hasRole('CUSTOMER')") @ResponseStatus(HttpStatus.CREATED) public CookingRequest create(@Valid @RequestBody CookingRequestPayload p,Authentication a){CampusOrder o=orders.findById(p.orderId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found"));if(!o.getCustomerEmail().equalsIgnoreCase(a.getName()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your order");if(o.getStatus()==OrderStatus.CANCELLED||o.getStatus()==OrderStatus.DELIVERED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Cannot add a cooking request to a completed order");return repo.save(new CookingRequest(o.getId(),a.getName(),o.getOutlet(),p.requestText().trim()));}
 @GetMapping("/my") @PreAuthorize("hasRole('CUSTOMER')") public List<CookingRequest> mine(Authentication a){return repo.findByCustomerEmailOrderByCreatedAtDesc(a.getName());}
 @GetMapping("/outlet") @PreAuthorize("hasAnyRole('STAFF','ADMIN','OWNER')") public List<CookingRequest> outlet(@RequestParam String outlet,Authentication a){AppUser u=users.findByEmail(a.getName()).orElseThrow();if(u.getRole()==Role.STAFF&&!outlet.equalsIgnoreCase(u.getAssignedOutlet()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Outside assigned outlet");return repo.findByOutletAndStatusNotOrderByCreatedAtAsc(outlet,"COMPLETED");}
 @PatchMapping("/{id}") @PreAuthorize("hasAnyRole('STAFF','ADMIN','OWNER')") public CookingRequest update(@PathVariable String id,@RequestParam String status,@RequestParam(required=false) String note,Authentication a){if(!List.of("SUBMITTED","ACCEPTED","PREPARING","COMPLETED","REJECTED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid request status");CookingRequest r=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Request not found"));AppUser u=users.findByEmail(a.getName()).orElseThrow();if(u.getRole()==Role.STAFF&&!r.getOutlet().equalsIgnoreCase(u.getAssignedOutlet()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Outside assigned outlet");r.update(status,note);return repo.save(r);}
}
